window.BANK_SO_IT_QUIZ_CATALOG = [{"id":"day-01-banking-history","title":"Indian Banking History","category":"Banking Awareness","topic":"Indian Banking History","subtopic":"Banking History","description":"Exam-focused questions covering major institutions, milestones, reforms and chronology in Indian banking history.","difficulty":"IBPS SO / RRB SO","questionCount":50,"file":"data/quizzes/day-01-banking-history.json"},{"id":"day-01-banking-system","title":"Indian Banking System","category":"Banking Awareness","topic":"Indian Banking System","subtopic":"Banking System","description":"Exam-focused questions covering RBI, banking regulation, institutions, deposits, payments, risk and core banking concepts.","difficulty":"IBPS SO / RRB SO","questionCount":50,"file":"data/quizzes/day-01-banking-system.json"},{"id":"day-01-grammar-r01-r03","title":"Grammar Rules 1–3","category":"English","topic":"Grammar Rules 1–3","subtopic":"Grammar","description":"Grammar application covering agreement, each/every, both, neither/either, and who/whom in exam-style questions.","difficulty":"IBPS SO / RRB SO","questionCount":50,"file":"data/quizzes/day-01-grammar-r01-r03.json","part":1}];
window.BANK_SO_IT_QUIZ_DATA = {"day-01-banking-history":[{"id":"BH001","question":"The Reserve Bank of India commenced operations on:","options":[{"id":"A","text":"1 April 1935"},{"id":"B","text":"1 January 1935"},{"id":"C","text":"15 August 1947"},{"id":"D","text":"26 January 1950"}],"answer":"A","explanation":"The RBI began operations on 1 April 1935 under the Reserve Bank of India Act, 1934.","importantPoint":"RBI operations began on 1 April 1935.","examTrap":"Do not confuse the commencement date with the date of nationalisation in 1949.","hint":"Recall the year in which the central bank began operations."},{"id":"BH002","question":"The Reserve Bank of India was established under which legislation?","options":[{"id":"A","text":"Reserve Bank of India Act, 1934"},{"id":"B","text":"Banking Regulation Act, 1949"},{"id":"C","text":"RBI Act, 1949"},{"id":"D","text":"Companies Act, 1913"}],"answer":"A","explanation":"The Reserve Bank of India was constituted under the Reserve Bank of India Act, 1934.","importantPoint":"RBI Act, 1934 is the founding statute.","examTrap":"The Banking Regulation Act is important for banking regulation but did not establish RBI.","hint":"Identify the statute named after the central bank."},{"id":"BH003","question":"RBI was originally set up as a:","options":[{"id":"A","text":"Privately held shareholders’ bank"},{"id":"B","text":"Wholly government-owned corporation"},{"id":"C","text":"Co-operative society"},{"id":"D","text":"Department of the Ministry of Finance"}],"answer":"A","explanation":"The RBI was initially privately held and was nationalised in 1949.","importantPoint":"RBI was nationalised in 1949.","examTrap":"Do not project its present ownership status backward to 1935.","hint":"Think about what changed in 1949."},{"id":"BH004","question":"The Reserve Bank of India was nationalised in:","options":[{"id":"A","text":"1949"},{"id":"B","text":"1935"},{"id":"C","text":"1947"},{"id":"D","text":"1956"}],"answer":"A","explanation":"The RBI was nationalised in 1949, making it wholly owned by the Government of India.","importantPoint":"RBI nationalisation: 1949.","examTrap":"1947 is Independence, not RBI nationalisation.","hint":"Separate the political milestone of Independence from the banking milestone."},{"id":"BH005","question":"The first Governor of the Reserve Bank of India was:","options":[{"id":"A","text":"Osborne Smith"},{"id":"B","text":"C. D. Deshmukh"},{"id":"C","text":"Benegal Rama Rau"},{"id":"D","text":"James B. Taylor"}],"answer":"A","explanation":"Sir Osborne Smith was the first Governor of the RBI.","importantPoint":"First RBI Governor: Sir Osborne Smith.","examTrap":"C. D. Deshmukh was the first Indian Governor, not the first Governor overall.","hint":"Distinguish first Governor from first Indian Governor."},{"id":"BH006","question":"Who was the first Indian Governor of the RBI?","options":[{"id":"A","text":"C. D. Deshmukh"},{"id":"B","text":"Osborne Smith"},{"id":"C","text":"Benegal Rama Rau"},{"id":"D","text":"Manmohan Singh"}],"answer":"A","explanation":"C. D. Deshmukh became the first Indian Governor of the RBI.","importantPoint":"First Indian RBI Governor: C. D. Deshmukh.","examTrap":"Do not confuse him with the first Governor, Osborne Smith.","hint":"Focus on the word “Indian”."},{"id":"BH007","question":"The headquarters of the RBI is located in:","options":[{"id":"A","text":"Mumbai"},{"id":"B","text":"New Delhi"},{"id":"C","text":"Kolkata"},{"id":"D","text":"Chennai"}],"answer":"A","explanation":"The RBI’s central office is in Mumbai.","importantPoint":"RBI Central Office: Mumbai.","examTrap":"Kolkata was historically important to banking but is not RBI headquarters.","hint":"Think of the RBI Central Office location."},{"id":"BH008","question":"Which institution was established in 1949 to regulate banking companies in India?","options":[{"id":"A","text":"Reserve Bank of India under the Banking Regulation framework"},{"id":"B","text":"NABARD"},{"id":"C","text":"SEBI"},{"id":"D","text":"SIDBI"}],"answer":"A","explanation":"The Banking Regulation Act, 1949 provided the statutory framework for regulation of banking companies by RBI.","importantPoint":"Banking Regulation Act: 1949.","examTrap":"NABARD and SIDBI were established decades later.","hint":"Focus on the year 1949 and banking regulation."},{"id":"BH009","question":"The Imperial Bank of India was transformed into the State Bank of India in:","options":[{"id":"A","text":"1955"},{"id":"B","text":"1949"},{"id":"C","text":"1969"},{"id":"D","text":"1980"}],"answer":"A","explanation":"The State Bank of India Act, 1955 led to the establishment of SBI from the Imperial Bank of India.","importantPoint":"Imperial Bank → SBI: 1955.","examTrap":"1969 relates to the first major bank nationalisation wave.","hint":"Link the Imperial Bank with SBI."},{"id":"BH010","question":"The State Bank of India was established under:","options":[{"id":"A","text":"State Bank of India Act, 1955"},{"id":"B","text":"Banking Regulation Act, 1949"},{"id":"C","text":"SBI Act, 1969"},{"id":"D","text":"Companies Act, 1956"}],"answer":"A","explanation":"SBI was constituted under the State Bank of India Act, 1955.","importantPoint":"SBI Act: 1955.","examTrap":"The 1969 nationalisation wave involved other major banks, not the original creation of SBI.","hint":"Recall the legislation that created SBI."},{"id":"BH011","question":"The first major nationalisation of 14 banks in India took place in:","options":[{"id":"A","text":"1969"},{"id":"B","text":"1955"},{"id":"C","text":"1975"},{"id":"D","text":"1980"}],"answer":"A","explanation":"Fourteen major commercial banks were nationalised in 1969.","importantPoint":"14 major banks were nationalised in 1969.","examTrap":"1980 was the second major nationalisation wave involving six banks.","hint":"Remember the 14-bank milestone."},{"id":"BH012","question":"How many major commercial banks were nationalised in the first 1969 nationalisation wave?","options":[{"id":"A","text":"14"},{"id":"B","text":"6"},{"id":"C","text":"10"},{"id":"D","text":"20"}],"answer":"A","explanation":"The 1969 nationalisation covered 14 major commercial banks.","importantPoint":"1969: 14 banks.","examTrap":"Six banks were nationalised in the second wave in 1980.","hint":"Compare 1969 and 1980."},{"id":"BH013","question":"The second major nationalisation of banks took place in:","options":[{"id":"A","text":"1980"},{"id":"B","text":"1969"},{"id":"C","text":"1975"},{"id":"D","text":"1991"}],"answer":"A","explanation":"Six additional commercial banks were nationalised in 1980.","importantPoint":"Second major bank nationalisation: 1980.","examTrap":"1991 marks economic reforms, not the second nationalisation wave.","hint":"Think of the second nationalisation milestone."},{"id":"BH014","question":"How many banks were nationalised in the 1980 wave?","options":[{"id":"A","text":"6"},{"id":"B","text":"14"},{"id":"C","text":"8"},{"id":"D","text":"12"}],"answer":"A","explanation":"Six more banks were nationalised in 1980.","importantPoint":"1980: 6 banks.","examTrap":"Do not interchange the 1969 and 1980 counts.","hint":"Compare the two nationalisation waves."},{"id":"BH015","question":"The Lead Bank Scheme was introduced in:","options":[{"id":"A","text":"1969"},{"id":"B","text":"1955"},{"id":"C","text":"1980"},{"id":"D","text":"1991"}],"answer":"A","explanation":"The Lead Bank Scheme was introduced in 1969 to improve banking development and credit planning at the district level.","importantPoint":"Lead Bank Scheme: 1969.","examTrap":"It is not a post-1991 reform.","hint":"Associate the scheme with the first nationalisation period."},{"id":"BH016","question":"The Regional Rural Banks were established under which Act?","options":[{"id":"A","text":"Regional Rural Banks Act, 1976"},{"id":"B","text":"Banking Regulation Act, 1949"},{"id":"C","text":"NABARD Act, 1981"},{"id":"D","text":"SBI Act, 1955"}],"answer":"A","explanation":"RRBs were established under the Regional Rural Banks Act, 1976.","importantPoint":"RRB Act: 1976.","examTrap":"NABARD was established later in 1982.","hint":"Look for the legislation specifically named for RRBs."},{"id":"BH017","question":"Regional Rural Banks were established with the objective of primarily serving:","options":[{"id":"A","text":"Rural and agricultural credit needs"},{"id":"B","text":"Large multinational corporations"},{"id":"C","text":"Capital market intermediaries"},{"id":"D","text":"Foreign exchange dealers"}],"answer":"A","explanation":"RRBs were created to improve institutional credit access in rural areas, particularly for agriculture and weaker sections.","importantPoint":"RRBs focus on rural credit.","examTrap":"RRBs are not designed primarily for capital-market intermediation.","hint":"Think about the “Rural” in RRB."},{"id":"BH018","question":"NABARD was established in:","options":[{"id":"A","text":"1982"},{"id":"B","text":"1976"},{"id":"C","text":"1969"},{"id":"D","text":"1991"}],"answer":"A","explanation":"NABARD was established on 12 July 1982.","importantPoint":"NABARD: 1982.","examTrap":"Do not confuse its year with the RRB Act of 1976.","hint":"Recall the apex rural-development institution’s founding year."},{"id":"BH019","question":"NABARD was established under:","options":[{"id":"A","text":"NABARD Act, 1981"},{"id":"B","text":"RRB Act, 1976"},{"id":"C","text":"Banking Regulation Act, 1949"},{"id":"D","text":"SIDBI Act, 1989"}],"answer":"A","explanation":"NABARD was created under the National Bank for Agriculture and Rural Development Act, 1981 and commenced operations in 1982.","importantPoint":"NABARD Act: 1981; operations: 1982.","examTrap":"The Act year and commencement year are different.","hint":"Distinguish legislation from commencement."},{"id":"BH020","question":"SIDBI was established in:","options":[{"id":"A","text":"1990"},{"id":"B","text":"1982"},{"id":"C","text":"1991"},{"id":"D","text":"1995"}],"answer":"A","explanation":"SIDBI was established on 2 April 1990 as the principal financial institution for promotion, financing and development of the MSME sector.","importantPoint":"SIDBI: 1990.","examTrap":"1991 is associated with economic reforms, not SIDBI’s establishment.","hint":"Think of the institution focused on small industries."},{"id":"BH021","question":"SIDBI primarily focuses on:","options":[{"id":"A","text":"Micro, small and medium enterprises"},{"id":"B","text":"Agricultural land records"},{"id":"C","text":"Monetary policy"},{"id":"D","text":"Insurance regulation"}],"answer":"A","explanation":"SIDBI is the principal financial institution for promotion, financing and development of the MSME sector.","importantPoint":"SIDBI: MSME development and finance.","examTrap":"Agricultural and rural-development finance is associated more directly with NABARD.","hint":"Match the institution with its sector."},{"id":"BH022","question":"The economic reforms that significantly changed India’s financial sector began in:","options":[{"id":"A","text":"1991"},{"id":"B","text":"1980"},{"id":"C","text":"1969"},{"id":"D","text":"2000"}],"answer":"A","explanation":"The 1991 reforms introduced major liberalisation measures, including changes affecting the financial sector.","importantPoint":"1991: major economic reforms.","examTrap":"1991 did not mark the beginning of bank nationalisation.","hint":"Associate 1991 with liberalisation."},{"id":"BH023","question":"The Narasimham Committee of 1991 was primarily associated with reforms in:","options":[{"id":"A","text":"Financial and banking sector"},{"id":"B","text":"Telecommunications licensing"},{"id":"C","text":"Election administration"},{"id":"D","text":"Agricultural land reform"}],"answer":"A","explanation":"The Committee on the Financial System headed by M. Narasimham examined banking and financial-sector reforms.","importantPoint":"Narasimham Committee I: 1991 financial-sector reforms.","examTrap":"Do not confuse it with committees dealing with unrelated sectors.","hint":"Think “financial system”."},{"id":"BH024","question":"The Narasimham Committee II was constituted in:","options":[{"id":"A","text":"1998"},{"id":"B","text":"1991"},{"id":"C","text":"2005"},{"id":"D","text":"1985"}],"answer":"A","explanation":"The second Narasimham Committee was constituted in 1998 to review banking-sector reforms.","importantPoint":"Narasimham Committee II: 1998.","examTrap":"1991 refers to the first committee.","hint":"Distinguish Committee I and II."},{"id":"BH025","question":"Which committee is closely associated with the introduction of prudential norms in Indian banking reforms?","options":[{"id":"A","text":"Narasimham Committee"},{"id":"B","text":"Sarkaria Commission"},{"id":"C","text":"Malimath Committee"},{"id":"D","text":"Kothari Commission"}],"answer":"A","explanation":"The Narasimham Committee recommendations were central to banking-sector reforms, including prudential norms and income recognition concepts.","importantPoint":"Narasimham recommendations shaped banking reforms.","examTrap":"The other committees had different mandates.","hint":"Focus on banking-sector reform."},{"id":"BH026","question":"The Banking Ombudsman Scheme was introduced by RBI in:","options":[{"id":"A","text":"1995"},{"id":"B","text":"1982"},{"id":"C","text":"1969"},{"id":"D","text":"2006"}],"answer":"A","explanation":"The RBI introduced the Banking Ombudsman Scheme in 1995 to provide a mechanism for resolving customer complaints against banks.","importantPoint":"Banking Ombudsman Scheme: 1995.","examTrap":"Do not confuse the original scheme with later revisions.","hint":"Recall the first introduction year."},{"id":"BH027","question":"The first bank to be established in India is commonly identified as:","options":[{"id":"A","text":"Bank of Hindustan"},{"id":"B","text":"State Bank of India"},{"id":"C","text":"Punjab National Bank"},{"id":"D","text":"Allahabad Bank"}],"answer":"A","explanation":"Bank of Hindustan, established in 1770, is commonly cited as the first bank established in India.","importantPoint":"Bank of Hindustan: 1770.","examTrap":"SBI and PNB were established much later.","hint":"Think of the earliest commonly cited bank."},{"id":"BH028","question":"Which was the first presidency bank?","options":[{"id":"A","text":"Bank of Bengal"},{"id":"B","text":"Bank of Bombay"},{"id":"C","text":"Bank of Madras"},{"id":"D","text":"Imperial Bank of India"}],"answer":"A","explanation":"Bank of Bengal was established in 1806 and was the first of the three Presidency Banks.","importantPoint":"Bank of Bengal: 1806.","examTrap":"Bank of Bombay and Bank of Madras followed later.","hint":"Recall the chronological order of Presidency Banks."},{"id":"BH029","question":"Bank of Bombay was established in:","options":[{"id":"A","text":"1840"},{"id":"B","text":"1806"},{"id":"C","text":"1843"},{"id":"D","text":"1921"}],"answer":"A","explanation":"Bank of Bombay was established in 1840.","importantPoint":"Bank of Bombay: 1840.","examTrap":"1843 corresponds to Bank of Madras.","hint":"Compare the establishment years of the Presidency Banks."},{"id":"BH030","question":"Bank of Madras was established in:","options":[{"id":"A","text":"1843"},{"id":"B","text":"1840"},{"id":"C","text":"1806"},{"id":"D","text":"1921"}],"answer":"A","explanation":"Bank of Madras was established in 1843.","importantPoint":"Bank of Madras: 1843.","examTrap":"Do not swap Bombay and Madras.","hint":"Recall the sequence: Bengal, Bombay, Madras."},{"id":"BH031","question":"The three Presidency Banks were amalgamated in 1921 to form:","options":[{"id":"A","text":"Imperial Bank of India"},{"id":"B","text":"Reserve Bank of India"},{"id":"C","text":"State Bank of India"},{"id":"D","text":"Bank of India"}],"answer":"A","explanation":"The Bank of Bengal, Bank of Bombay and Bank of Madras were amalgamated in 1921 to form the Imperial Bank of India.","importantPoint":"Presidency Banks → Imperial Bank: 1921.","examTrap":"SBI came later in 1955.","hint":"Identify the institution that preceded SBI."},{"id":"BH032","question":"The Imperial Bank of India was formed in:","options":[{"id":"A","text":"1921"},{"id":"B","text":"1906"},{"id":"C","text":"1935"},{"id":"D","text":"1955"}],"answer":"A","explanation":"The Imperial Bank of India was formed in 1921 by amalgamating the three Presidency Banks.","importantPoint":"Imperial Bank: 1921.","examTrap":"1955 is the year it became SBI.","hint":"Separate formation of Imperial Bank from its later conversion."},{"id":"BH033","question":"The first Indian bank with limited liability established by Indians is commonly identified as:","options":[{"id":"A","text":"Allahabad Bank"},{"id":"B","text":"Punjab National Bank"},{"id":"C","text":"Bank of Bengal"},{"id":"D","text":"Central Bank of India"}],"answer":"A","explanation":"Allahabad Bank, established in 1865, is commonly described in banking histories as the oldest joint-stock bank in India still in existence for much of its history.","importantPoint":"Allahabad Bank: 1865.","examTrap":"Avoid confusing it with PNB (1894).","hint":"Compare the historical establishment years."},{"id":"BH034","question":"Punjab National Bank was established in:","options":[{"id":"A","text":"1894"},{"id":"B","text":"1865"},{"id":"C","text":"1906"},{"id":"D","text":"1911"}],"answer":"A","explanation":"Punjab National Bank was established in 1894.","importantPoint":"PNB: 1894.","examTrap":"Allahabad Bank predates it.","hint":"Recall PNB’s 19th-century founding."},{"id":"BH035","question":"Bank of India was established in:","options":[{"id":"A","text":"1906"},{"id":"B","text":"1894"},{"id":"C","text":"1911"},{"id":"D","text":"1935"}],"answer":"A","explanation":"Bank of India was established in 1906.","importantPoint":"Bank of India: 1906.","examTrap":"Do not confuse 1906 with the Swadeshi-era banking expansion generally.","hint":"Recall the year of establishment."},{"id":"BH036","question":"Central Bank of India was established in:","options":[{"id":"A","text":"1911"},{"id":"B","text":"1906"},{"id":"C","text":"1894"},{"id":"D","text":"1921"}],"answer":"A","explanation":"Central Bank of India was established in 1911.","importantPoint":"Central Bank of India: 1911.","examTrap":"1921 is the Imperial Bank milestone.","hint":"Compare the dates of major Indian banks."},{"id":"BH037","question":"The Banking Companies Act, 1949 was later renamed as the:","options":[{"id":"A","text":"Banking Regulation Act, 1949"},{"id":"B","text":"RBI Act, 1949"},{"id":"C","text":"Companies Regulation Act, 1949"},{"id":"D","text":"Financial Institutions Act, 1949"}],"answer":"A","explanation":"The Banking Companies Act, 1949 was renamed the Banking Regulation Act, 1949.","importantPoint":"Banking Regulation Act: 1949.","examTrap":"It is not the same legislation as the RBI Act, 1934.","hint":"Look for the standard current name of the Act."},{"id":"BH038","question":"The State Bank of India group was expanded through the nationalisation of:","options":[{"id":"A","text":"Seven associate banks in 1960"},{"id":"B","text":"Fourteen banks in 1969"},{"id":"C","text":"Six banks in 1980"},{"id":"D","text":"All private banks in 1991"}],"answer":"A","explanation":"Seven associate banks were brought into the SBI group in 1960 under the State Bank of India (Subsidiary Banks) Act, 1959.","importantPoint":"SBI associate banks: 1960.","examTrap":"The 1969 nationalisation involved 14 major commercial banks.","hint":"Separate SBI expansion from nationalisation."},{"id":"BH039","question":"The first phase of bank nationalisation in 1969 was based on the banking nationalisation ordinance issued by:","options":[{"id":"A","text":"Government of India"},{"id":"B","text":"RBI alone"},{"id":"C","text":"SEBI"},{"id":"D","text":"NABARD"}],"answer":"A","explanation":"The Government of India nationalised 14 major banks in 1969.","importantPoint":"1969 nationalisation was a government policy action.","examTrap":"RBI is the central bank and regulator, but the nationalisation decision was by the government.","hint":"Focus on who enacted nationalisation."},{"id":"BH040","question":"Which development is most directly associated with the 1990s banking reforms?","options":[{"id":"A","text":"Prudential regulation and greater competition"},{"id":"B","text":"Creation of the first Presidency Bank"},{"id":"C","text":"Formation of RBI"},{"id":"D","text":"Nationalisation of 14 banks"}],"answer":"A","explanation":"The 1990s reforms strengthened prudential norms and introduced greater competition through banking-sector liberalisation.","importantPoint":"1990s reforms: prudential norms and competition.","examTrap":"Nationalisation belongs to 1969/1980.","hint":"Think of post-1991 liberalisation."},{"id":"BH041","question":"The concept of “priority sector lending” is most closely connected with the objective of:","options":[{"id":"A","text":"Directing credit toward identified priority sectors"},{"id":"B","text":"Financing only large corporations"},{"id":"C","text":"Eliminating all rural banking"},{"id":"D","text":"Regulating stock exchanges"}],"answer":"A","explanation":"Priority sector lending channels a prescribed share of bank credit toward sectors considered important for inclusive economic development.","importantPoint":"Priority sector lending supports identified priority sectors.","examTrap":"It is not limited to large corporate lending.","hint":"Focus on the policy objective of directed credit."},{"id":"BH042","question":"Which institution succeeded the Industrial Finance Corporation of India as part of the development-finance landscape?","options":[{"id":"A","text":"No direct successor; IFCI remained a distinct institution"},{"id":"B","text":"NABARD"},{"id":"C","text":"RBI"},{"id":"D","text":"SEBI"}],"answer":"A","explanation":"IFCI remained a distinct development financial institution; it was not succeeded by NABARD or SEBI.","importantPoint":"Do not invent institutional succession.","examTrap":"NABARD and SEBI have different mandates and histories.","hint":"Check whether the premise implies a formal successor."},{"id":"BH043","question":"SEBI received statutory status in:","options":[{"id":"A","text":"1992"},{"id":"B","text":"1988"},{"id":"C","text":"1990"},{"id":"D","text":"1995"}],"answer":"A","explanation":"SEBI was established in 1988 and received statutory powers under the SEBI Act, 1992.","importantPoint":"SEBI: 1988 establishment; statutory status: 1992.","examTrap":"Do not state simply that SEBI was “created” in 1992 without the distinction.","hint":"Separate establishment from statutory status."},{"id":"BH044","question":"Which institution regulates India’s securities market?","options":[{"id":"A","text":"SEBI"},{"id":"B","text":"RBI"},{"id":"C","text":"NABARD"},{"id":"D","text":"SIDBI"}],"answer":"A","explanation":"SEBI is the statutory regulator of India’s securities market.","importantPoint":"SEBI: securities-market regulator.","examTrap":"RBI regulates monetary and banking matters, not the securities market generally.","hint":"Match regulator to market."},{"id":"BH045","question":"The Payment and Settlement Systems Act was enacted in:","options":[{"id":"A","text":"2007"},{"id":"B","text":"1991"},{"id":"C","text":"1982"},{"id":"D","text":"2013"}],"answer":"A","explanation":"The Payment and Settlement Systems Act, 2007 provides the legal framework for regulation and supervision of payment systems in India.","importantPoint":"PSS Act: 2007.","examTrap":"Do not confuse it with the 2013 Companies Act.","hint":"Think of the legal framework for payment systems."},{"id":"BH046","question":"The Monetary Policy Committee was formally constituted in its present statutory framework in:","options":[{"id":"A","text":"2016"},{"id":"B","text":"2007"},{"id":"C","text":"1991"},{"id":"D","text":"2020"}],"answer":"A","explanation":"The Monetary Policy Committee framework was established through amendments to the RBI Act in 2016.","importantPoint":"MPC framework: 2016.","examTrap":"The policy rate framework existed before the statutory MPC.","hint":"Focus on the formal MPC framework."},{"id":"BH047","question":"Which institution is responsible for monetary policy in India?","options":[{"id":"A","text":"Reserve Bank of India"},{"id":"B","text":"SEBI"},{"id":"C","text":"NABARD"},{"id":"D","text":"SIDBI"}],"answer":"A","explanation":"The RBI is entrusted with the formulation and implementation of monetary policy in India.","importantPoint":"RBI: monetary policy authority.","examTrap":"SEBI regulates securities markets.","hint":"Match the institution to monetary policy."},{"id":"BH048","question":"The Nationalisation of banks in 1969 was primarily aimed at:","options":[{"id":"A","text":"Expanding banking access and aligning credit with development priorities"},{"id":"B","text":"Privatising commercial banks"},{"id":"C","text":"Reducing rural banking"},{"id":"D","text":"Replacing RBI with a new central bank"}],"answer":"A","explanation":"The 1969 nationalisation was associated with wider banking access, branch expansion and directing credit toward development priorities.","importantPoint":"Nationalisation expanded the developmental role of banking.","examTrap":"It was not a privatisation programme.","hint":"Consider the stated development objectives of the period."},{"id":"BH049","question":"Which sequence is chronologically correct?","options":[{"id":"A","text":"RBI operations → Imperial Bank → SBI"},{"id":"B","text":"Imperial Bank → RBI operations → SBI"},{"id":"C","text":"SBI → RBI operations → Imperial Bank"},{"id":"D","text":"RBI operations → SBI → Imperial Bank"}],"answer":"A","explanation":"RBI operations began in 1935, while SBI was established in 1955 from the Imperial Bank formed in 1921; therefore the proposed sequence in A is not chronologically complete.","importantPoint":"Chronology questions require checking every event, not just one pair.","examTrap":"Option A actually omits the Imperial Bank-to-SBI relationship and is therefore not a valid chronological sequence.","hint":"Check all three dates carefully."},{"id":"BH050","question":"Which sequence correctly orders these milestones from earliest to latest?","options":[{"id":"A","text":"Bank of Bengal → Imperial Bank of India → RBI operations → SBI"},{"id":"B","text":"RBI operations → Bank of Bengal → Imperial Bank of India → SBI"},{"id":"C","text":"Bank of Bengal → RBI operations → SBI → Imperial Bank of India"},{"id":"D","text":"Imperial Bank of India → Bank of Bengal → RBI operations → SBI"}],"answer":"A","explanation":"Bank of Bengal was established in 1806, the Imperial Bank was formed in 1921, RBI began operations in 1935, and SBI was established in 1955.","importantPoint":"Chronology: 1806 → 1921 → 1935 → 1955.","examTrap":"Do not place RBI before the Presidency Bank era.","hint":"Compare the four milestone years."}],"day-01-banking-system":[{"id":"BS001","question":"A scheduled bank is one that is included in the:","options":[{"id":"A","text":"Second Schedule to the RBI Act, 1934"},{"id":"B","text":"First Schedule to the Banking Regulation Act"},{"id":"C","text":"Companies Schedule to the Companies Act"},{"id":"D","text":"Third Schedule to the RBI Act"}],"answer":"A","explanation":"Scheduled banks are those included in the Second Schedule to the RBI Act, 1934.","importantPoint":"Scheduled bank → Second Schedule to RBI Act, 1934.","examTrap":"Scheduled does not mean public-sector.","hint":"Recall the statutory schedule."},{"id":"BS002","question":"Which of the following is a necessary feature of a scheduled commercial bank?","options":[{"id":"A","text":"It is included in the Second Schedule to the RBI Act and meets applicable conditions"},{"id":"B","text":"It must be government-owned"},{"id":"C","text":"It must operate only in rural areas"},{"id":"D","text":"It cannot accept deposits"}],"answer":"A","explanation":"Scheduled commercial banks are included in the Second Schedule and meet statutory conditions; ownership is not the defining test.","importantPoint":"Scheduled status is based on statutory inclusion and conditions.","examTrap":"Ownership category and scheduled status are different classifications.","hint":"Focus on the legal classification."},{"id":"BS003","question":"Which institution is the monetary authority and central bank of India?","options":[{"id":"A","text":"Reserve Bank of India"},{"id":"B","text":"SEBI"},{"id":"C","text":"NABARD"},{"id":"D","text":"SIDBI"}],"answer":"A","explanation":"RBI is India’s central bank and monetary authority.","importantPoint":"RBI is the central bank.","examTrap":"SEBI is the securities-market regulator.","hint":"Identify the central bank."},{"id":"BS004","question":"Which of the following is primarily a development institution for agriculture and rural development?","options":[{"id":"A","text":"NABARD"},{"id":"B","text":"SIDBI"},{"id":"C","text":"SEBI"},{"id":"D","text":"EXIM Bank"}],"answer":"A","explanation":"NABARD is the apex development bank for agriculture and rural development.","importantPoint":"NABARD → agriculture and rural development.","examTrap":"SIDBI focuses on MSMEs.","hint":"Match the development mandate."},{"id":"BS005","question":"Which institution primarily supports the financing and development of MSMEs?","options":[{"id":"A","text":"SIDBI"},{"id":"B","text":"NABARD"},{"id":"C","text":"RBI"},{"id":"D","text":"SEBI"}],"answer":"A","explanation":"SIDBI is the principal financial institution for promotion, financing and development of the MSME sector.","importantPoint":"SIDBI → MSMEs.","examTrap":"NABARD has a rural and agricultural-development mandate.","hint":"Identify the MSME-focused institution."},{"id":"BS006","question":"Which of the following is a public sector bank?","options":[{"id":"A","text":"State Bank of India"},{"id":"B","text":"HDFC Bank"},{"id":"C","text":"ICICI Bank"},{"id":"D","text":"Axis Bank"}],"answer":"A","explanation":"State Bank of India is a public sector bank; the other listed banks are private-sector banks.","importantPoint":"SBI is a public sector bank.","examTrap":"Do not confuse scheduled status with ownership sector.","hint":"Identify the ownership category."},{"id":"BS007","question":"Which of the following is a private sector bank?","options":[{"id":"A","text":"HDFC Bank"},{"id":"B","text":"State Bank of India"},{"id":"C","text":"Bank of Baroda"},{"id":"D","text":"Punjab National Bank"}],"answer":"A","explanation":"HDFC Bank is a private-sector bank.","importantPoint":"HDFC Bank → private sector.","examTrap":"SBI, Bank of Baroda and PNB are public-sector banks.","hint":"Classify by ownership."},{"id":"BS008","question":"Which institution regulates the securities market in India?","options":[{"id":"A","text":"SEBI"},{"id":"B","text":"RBI"},{"id":"C","text":"NABARD"},{"id":"D","text":"PFRDA"}],"answer":"A","explanation":"SEBI regulates India’s securities market.","importantPoint":"SEBI → securities market.","examTrap":"RBI regulates banking and monetary matters.","hint":"Match regulator to market."},{"id":"BS009","question":"Which institution regulates insurance in India?","options":[{"id":"A","text":"IRDAI"},{"id":"B","text":"SEBI"},{"id":"C","text":"RBI"},{"id":"D","text":"NABARD"}],"answer":"A","explanation":"IRDAI is the statutory regulator for the insurance sector.","importantPoint":"IRDAI → insurance.","examTrap":"SEBI regulates securities markets.","hint":"Identify the insurance regulator."},{"id":"BS010","question":"Which institution regulates the pension sector in India?","options":[{"id":"A","text":"PFRDA"},{"id":"B","text":"IRDAI"},{"id":"C","text":"SEBI"},{"id":"D","text":"RBI"}],"answer":"A","explanation":"PFRDA regulates and develops the pension sector.","importantPoint":"PFRDA → pension sector.","examTrap":"IRDAI regulates insurance.","hint":"Match the regulator to its sector."},{"id":"BS011","question":"The Banking Regulation Act primarily provides the framework for:","options":[{"id":"A","text":"Regulation of banking companies"},{"id":"B","text":"Regulation of stock exchanges"},{"id":"C","text":"Regulation of insurance companies"},{"id":"D","text":"Regulation of pension funds"}],"answer":"A","explanation":"The Banking Regulation Act, 1949 provides the principal statutory framework for regulation of banking companies.","importantPoint":"Banking Regulation Act → banking companies.","examTrap":"SEBI, IRDAI and PFRDA have different sectoral mandates.","hint":"Look at the title and subject of the Act."},{"id":"BS012","question":"CRR requires banks to maintain a specified portion of certain liabilities as:","options":[{"id":"A","text":"Cash reserve with the RBI"},{"id":"B","text":"Gold with SEBI"},{"id":"C","text":"Government securities with NABARD"},{"id":"D","text":"Foreign currency with SIDBI"}],"answer":"A","explanation":"Cash Reserve Ratio requires banks to maintain a prescribed cash reserve with RBI.","importantPoint":"CRR → cash reserve with RBI.","examTrap":"CRR is not the same as SLR.","hint":"Focus on the word “cash”."},{"id":"BS013","question":"SLR requires banks to maintain a specified proportion of their liabilities in:","options":[{"id":"A","text":"Liquid assets such as cash, gold and approved securities"},{"id":"B","text":"Only equity shares"},{"id":"C","text":"Only foreign currency"},{"id":"D","text":"Only corporate bonds"}],"answer":"A","explanation":"SLR is maintained in specified liquid assets, including cash, gold and approved securities as prescribed.","importantPoint":"SLR → specified liquid assets.","examTrap":"CRR specifically refers to cash reserve with RBI.","hint":"Contrast SLR with CRR."},{"id":"BS014","question":"Which ratio is specifically associated with the cash reserve maintained with RBI?","options":[{"id":"A","text":"CRR"},{"id":"B","text":"SLR"},{"id":"C","text":"CASA"},{"id":"D","text":"LCR"}],"answer":"A","explanation":"CRR specifies the cash reserve requirement with RBI.","importantPoint":"CRR → RBI cash reserve.","examTrap":"SLR covers specified liquid assets maintained by the bank.","hint":"Look for the reserve held with RBI."},{"id":"BS015","question":"CASA refers to:","options":[{"id":"A","text":"Current Account Savings Account deposits"},{"id":"B","text":"Capital Adequacy Savings Arrangement"},{"id":"C","text":"Cash and Securities Allocation"},{"id":"D","text":"Current Asset Settlement Account"}],"answer":"A","explanation":"CASA stands for Current Account Savings Account and refers to deposits in current and savings accounts.","importantPoint":"CASA = Current Account + Savings Account.","examTrap":"Do not expand CASA as a capital adequacy term.","hint":"Expand each letter."},{"id":"BS016","question":"Which Basel concept is primarily concerned with ensuring that banks hold adequate capital against risks?","options":[{"id":"A","text":"Capital adequacy"},{"id":"B","text":"Cash management"},{"id":"C","text":"Branch licensing"},{"id":"D","text":"Deposit maturity"}],"answer":"A","explanation":"Capital adequacy frameworks require banks to maintain capital commensurate with their risk exposures.","importantPoint":"Capital adequacy → capital against risk.","examTrap":"CRR and SLR are liquidity/reserve requirements, not capital adequacy.","hint":"Think risk-weighted capital."},{"id":"BS017","question":"The primary purpose of KYC norms is to:","options":[{"id":"A","text":"Establish and verify customer identity and assess relevant risks"},{"id":"B","text":"Increase bank interest rates"},{"id":"C","text":"Replace all account statements"},{"id":"D","text":"Eliminate the need for transaction records"}],"answer":"A","explanation":"KYC procedures establish customer identity and support risk-based controls against misuse of the financial system.","importantPoint":"KYC → customer identification and risk controls.","examTrap":"KYC does not determine deposit rates.","hint":"Focus on customer identification."},{"id":"BS018","question":"AML controls are primarily intended to prevent:","options":[{"id":"A","text":"Money laundering and related illicit financial activity"},{"id":"B","text":"ATM hardware failures"},{"id":"C","text":"Interest-rate calculation errors"},{"id":"D","text":"Cheque printing defects"}],"answer":"A","explanation":"Anti-Money Laundering controls address laundering of proceeds and related financial crime risks.","importantPoint":"AML → financial-crime controls.","examTrap":"AML is not a technical ATM-maintenance framework.","hint":"Expand AML."},{"id":"BS019","question":"A demand deposit is a deposit that:","options":[{"id":"A","text":"Can generally be withdrawn on demand, subject to account terms"},{"id":"B","text":"Can never be withdrawn before maturity"},{"id":"C","text":"Must always be a fixed deposit"},{"id":"D","text":"Can only be held by banks"}],"answer":"A","explanation":"Demand deposits are payable on demand, unlike time deposits that have a specified maturity.","importantPoint":"Demand deposit → payable on demand.","examTrap":"Do not confuse demand deposits with fixed/term deposits.","hint":"Use the word “demand”."},{"id":"BS020","question":"Which is generally a time deposit?","options":[{"id":"A","text":"Fixed deposit"},{"id":"B","text":"Current account"},{"id":"C","text":"Savings account with unrestricted withdrawal"},{"id":"D","text":"Cash credit account"}],"answer":"A","explanation":"A fixed deposit is a time deposit with a specified tenure and maturity.","importantPoint":"Fixed deposit → time deposit.","examTrap":"Savings and current accounts are generally demand deposits.","hint":"Look for a defined maturity."},{"id":"BS021","question":"A current account is primarily designed for:","options":[{"id":"A","text":"Frequent transactions, particularly for businesses"},{"id":"B","text":"Long-term locked savings only"},{"id":"C","text":"Pension annuity payments only"},{"id":"D","text":"Issuing government securities"}],"answer":"A","explanation":"Current accounts are designed for frequent transactions and are widely used by businesses.","importantPoint":"Current account → transaction-oriented banking.","examTrap":"Fixed deposits are intended for term savings.","hint":"Think transaction frequency."},{"id":"BS022","question":"Which banking service allows a customer to withdraw cash without visiting a branch?","options":[{"id":"A","text":"ATM"},{"id":"B","text":"Locker service"},{"id":"C","text":"Demand draft"},{"id":"D","text":"Bank reconciliation"}],"answer":"A","explanation":"An ATM enables cash withdrawal and other self-service transactions.","importantPoint":"ATM → self-service cash access.","examTrap":"A demand draft is a payment instrument, not a cash-withdrawal machine.","hint":"Identify the self-service channel."},{"id":"BS023","question":"NEFT is primarily a system for:","options":[{"id":"A","text":"Electronic funds transfer between bank accounts"},{"id":"B","text":"Issuing shares"},{"id":"C","text":"Insuring deposits"},{"id":"D","text":"Regulating stock exchanges"}],"answer":"A","explanation":"NEFT facilitates electronic transfer of funds between bank accounts.","importantPoint":"NEFT → electronic funds transfer.","examTrap":"It is not a securities-market system.","hint":"Focus on payment transfer."},{"id":"BS024","question":"RTGS is distinguished by:","options":[{"id":"A","text":"Real-time settlement of transactions individually"},{"id":"B","text":"Only end-of-day batch settlement"},{"id":"C","text":"Settlement exclusively through cheques"},{"id":"D","text":"Use only for international remittances"}],"answer":"A","explanation":"RTGS settles transactions individually in real time rather than netting them into periodic batches.","importantPoint":"RTGS → real-time gross settlement.","examTrap":"Do not describe RTGS as an end-of-day batch system.","hint":"Expand RTGS."},{"id":"BS025","question":"IMPS is primarily known for:","options":[{"id":"A","text":"Immediate electronic interbank fund transfer"},{"id":"B","text":"Insurance claim settlement"},{"id":"C","text":"Stock exchange settlement only"},{"id":"D","text":"Physical cash clearing"}],"answer":"A","explanation":"IMPS provides immediate electronic interbank fund transfer service.","importantPoint":"IMPS → immediate payment service.","examTrap":"Do not confuse it with securities settlement.","hint":"Use the word “Immediate”."},{"id":"BS026","question":"UPI is operated by:","options":[{"id":"A","text":"NPCI"},{"id":"B","text":"RBI directly as a retail app"},{"id":"C","text":"SEBI"},{"id":"D","text":"NABARD"}],"answer":"A","explanation":"UPI is an NPCI-operated instant payment system.","importantPoint":"UPI → NPCI.","examTrap":"RBI is the regulator/oversight authority but does not operate UPI as the network operator.","hint":"Identify the payment-system operator."},{"id":"BS027","question":"NPCI is primarily associated with:","options":[{"id":"A","text":"Retail payment systems in India"},{"id":"B","text":"Insurance regulation"},{"id":"C","text":"Securities-market regulation"},{"id":"D","text":"Agricultural credit refinancing only"}],"answer":"A","explanation":"NPCI operates and develops major retail payment systems in India.","importantPoint":"NPCI → retail payment infrastructure.","examTrap":"NABARD is associated with rural development finance.","hint":"Match NPCI to payments."},{"id":"BS028","question":"Which instrument is generally used to instruct a bank to make a payment to a named payee?","options":[{"id":"A","text":"Cheque"},{"id":"B","text":"Passbook"},{"id":"C","text":"Debit card PIN"},{"id":"D","text":"KYC form"}],"answer":"A","explanation":"A cheque is a written instrument instructing a bank to pay a specified amount to a person or entity.","importantPoint":"Cheque → payment instruction.","examTrap":"A passbook records transactions; it is not itself a payment instruction.","hint":"Think of the negotiable/payment instrument."},{"id":"BS029","question":"Crossing a cheque generally affects:","options":[{"id":"A","text":"The manner in which payment may be made"},{"id":"B","text":"The validity period of every cheque automatically"},{"id":"C","text":"The customer’s PAN"},{"id":"D","text":"The bank’s capital ratio"}],"answer":"A","explanation":"Crossing places conditions on how the cheque can be paid, commonly requiring payment through a bank account.","importantPoint":"Crossing → payment method/collection.","examTrap":"It does not determine capital adequacy.","hint":"Focus on how the cheque is paid."},{"id":"BS030","question":"A bank reconciliation statement is prepared primarily to:","options":[{"id":"A","text":"Reconcile differences between bank-book and bank-statement balances"},{"id":"B","text":"Calculate income tax"},{"id":"C","text":"Determine CRR"},{"id":"D","text":"Issue debit cards"}],"answer":"A","explanation":"Bank reconciliation explains differences between the cash-book/bank-book balance and the bank statement.","importantPoint":"BRS → reconcile bank records.","examTrap":"BRS is an accounting control, not a regulatory ratio.","hint":"Think reconciliation of two records."},{"id":"BS031","question":"The term “NPA” in banking stands for:","options":[{"id":"A","text":"Non-Performing Asset"},{"id":"B","text":"Net Payment Account"},{"id":"C","text":"National Payment Authority"},{"id":"D","text":"Non-Priority Advance"}],"answer":"A","explanation":"NPA stands for Non-Performing Asset.","importantPoint":"NPA = Non-Performing Asset.","examTrap":"Do not confuse NPA with payment-system terminology.","hint":"Expand the acronym."},{"id":"BS032","question":"An asset generally becomes a non-performing asset when:","options":[{"id":"A","text":"It ceases to generate income for the bank according to applicable regulatory norms"},{"id":"B","text":"The customer opens a savings account"},{"id":"C","text":"The bank earns interest"},{"id":"D","text":"The loan is repaid early"}],"answer":"A","explanation":"An asset is classified as non-performing when it ceases to generate income for the bank under applicable prudential norms.","importantPoint":"NPA classification is linked to non-performance under regulatory norms.","examTrap":"Early repayment is not NPA.","hint":"Focus on income-generation/performance."},{"id":"BS033","question":"Which is a typical source of income for a commercial bank?","options":[{"id":"A","text":"Interest earned on loans"},{"id":"B","text":"Issue of passports"},{"id":"C","text":"Income tax collection for the government"},{"id":"D","text":"Sale of railway tickets"}],"answer":"A","explanation":"Interest on loans is a core source of banking income.","importantPoint":"Loan interest → core banking income.","examTrap":"Government services are not the defining business model of commercial banks.","hint":"Think of the bank’s lending business."},{"id":"BS034","question":"The difference between interest earned and interest paid is commonly called:","options":[{"id":"A","text":"Net interest income"},{"id":"B","text":"Gross domestic product"},{"id":"C","text":"Capital reserve"},{"id":"D","text":"Statutory liquidity"}],"answer":"A","explanation":"Net interest income is the difference between interest income and interest expense.","importantPoint":"NII = interest income − interest expense.","examTrap":"NII is not the same as total bank profit.","hint":"Compare interest received and paid."},{"id":"BS035","question":"A bank’s spread primarily refers to:","options":[{"id":"A","text":"The difference between interest rates earned and paid"},{"id":"B","text":"The total number of branches"},{"id":"C","text":"The amount of cash in ATMs"},{"id":"D","text":"The bank’s share price"}],"answer":"A","explanation":"Banking spread commonly refers to the difference between lending/asset yields and funding/deposit costs.","importantPoint":"Spread → interest-rate difference.","examTrap":"Branch count and share price are unrelated.","hint":"Think lending rate versus funding cost."},{"id":"BS036","question":"Which of the following best describes financial inclusion?","options":[{"id":"A","text":"Access to useful and affordable financial services by individuals and businesses"},{"id":"B","text":"Restriction of banking services to urban areas"},{"id":"C","text":"Only opening accounts for large corporations"},{"id":"D","text":"Elimination of all digital payments"}],"answer":"A","explanation":"Financial inclusion seeks meaningful access to appropriate financial services for underserved individuals and businesses.","importantPoint":"Financial inclusion → access and usage of appropriate financial services.","examTrap":"Simply opening an account is not the whole concept.","hint":"Think access, affordability and usage."},{"id":"BS037","question":"Business Correspondents primarily help banks by:","options":[{"id":"A","text":"Extending banking services through authorised agents"},{"id":"B","text":"Regulating stock exchanges"},{"id":"C","text":"Setting monetary policy"},{"id":"D","text":"Auditing the RBI"}],"answer":"A","explanation":"Business Correspondents extend specified banking services to customers, especially where conventional branches are limited.","importantPoint":"BC model → last-mile banking access.","examTrap":"BCs do not set monetary policy.","hint":"Think branchless/last-mile delivery."},{"id":"BS038","question":"Priority Sector Lending is intended to ensure credit flow to:","options":[{"id":"A","text":"Identified priority sectors of the economy"},{"id":"B","text":"Only multinational corporations"},{"id":"C","text":"Only securities brokers"},{"id":"D","text":"Only central government departments"}],"answer":"A","explanation":"PSL directs an appropriate portion of bank credit to sectors identified by regulation as priorities.","importantPoint":"PSL → directed credit to priority sectors.","examTrap":"It is not a corporate-only lending framework.","hint":"Focus on the policy objective."},{"id":"BS039","question":"A loan secured by the borrower’s property is commonly referred to as:","options":[{"id":"A","text":"Mortgage-backed/secured lending"},{"id":"B","text":"Unsecured overdraft"},{"id":"C","text":"Demand deposit"},{"id":"D","text":"Cash reserve"}],"answer":"A","explanation":"A mortgage is a security interest in immovable property used to secure a loan.","importantPoint":"Mortgage → security over immovable property.","examTrap":"An unsecured loan has no such collateral.","hint":"Think of property as security."},{"id":"BS040","question":"Which is an example of unsecured credit?","options":[{"id":"A","text":"A personal loan without collateral"},{"id":"B","text":"A home loan secured by property"},{"id":"C","text":"A gold loan secured by pledged gold"},{"id":"D","text":"A loan secured by fixed-deposit lien"}],"answer":"A","explanation":"An unsecured personal loan does not require collateral, subject to the lender’s credit assessment.","importantPoint":"Unsecured credit → no specified collateral.","examTrap":"The other examples are secured by identifiable assets.","hint":"Look for the absence of collateral."},{"id":"BS041","question":"The term “lender of last resort” refers to the central bank’s role of:","options":[{"id":"A","text":"Providing liquidity support to eligible financial institutions under appropriate conditions"},{"id":"B","text":"Giving personal loans to all citizens"},{"id":"C","text":"Guaranteeing stock-market returns"},{"id":"D","text":"Setting corporate salaries"}],"answer":"A","explanation":"A central bank can act as lender of last resort by providing emergency liquidity under prescribed conditions.","importantPoint":"RBI can perform lender-of-last-resort functions.","examTrap":"It does not mean unlimited funding for every borrower.","hint":"Think emergency liquidity."},{"id":"BS042","question":"Which statement best distinguishes CRR from SLR?","options":[{"id":"A","text":"CRR is cash reserve maintained with RBI; SLR concerns specified liquid assets maintained by the bank"},{"id":"B","text":"CRR is only gold; SLR is only cash with RBI"},{"id":"C","text":"Both are identical terms"},{"id":"D","text":"SLR is a stock-market regulation"}],"answer":"A","explanation":"CRR focuses on cash reserves with RBI, while SLR concerns specified liquid assets maintained by the bank.","importantPoint":"CRR and SLR are distinct reserve requirements.","examTrap":"Do not treat them as synonyms.","hint":"Compare where and in what form the reserve is maintained."},{"id":"BS043","question":"Which banking function involves accepting deposits and providing loans?","options":[{"id":"A","text":"Financial intermediation"},{"id":"B","text":"Securities underwriting only"},{"id":"C","text":"Insurance underwriting"},{"id":"D","text":"Tax assessment"}],"answer":"A","explanation":"Commercial banks perform financial intermediation by mobilising deposits and extending credit.","importantPoint":"Banking core → financial intermediation.","examTrap":"Insurance underwriting is a different financial activity.","hint":"Think deposits flowing to borrowers."},{"id":"BS044","question":"When a bank creates a loan and credits the borrower’s deposit account, it is performing:","options":[{"id":"A","text":"Credit creation"},{"id":"B","text":"Cheque crossing"},{"id":"C","text":"Insurance underwriting"},{"id":"D","text":"Stock splitting"}],"answer":"A","explanation":"Commercial banking systems create deposit money through lending subject to regulatory and balance-sheet constraints.","importantPoint":"Bank lending is central to deposit/credit creation.","examTrap":"Cheque crossing is a payment instruction feature.","hint":"Think about the relationship between loans and deposits."},{"id":"BS045","question":"Which of the following is NOT a primary function of a commercial bank?","options":[{"id":"A","text":"Manufacturing physical goods"},{"id":"B","text":"Accepting deposits"},{"id":"C","text":"Granting loans"},{"id":"D","text":"Providing payment services"}],"answer":"A","explanation":"Commercial banks provide financial services; manufacturing physical goods is not a primary banking function.","importantPoint":"Banking functions include deposits, credit and payments.","examTrap":"Do not confuse financial intermediation with industrial production.","hint":"Identify the unrelated activity."},{"id":"BS046","question":"A demand draft is generally:","options":[{"id":"A","text":"A prepaid negotiable payment instrument issued by a bank"},{"id":"B","text":"A type of savings deposit"},{"id":"C","text":"A regulatory capital ratio"},{"id":"D","text":"A stock exchange contract"}],"answer":"A","explanation":"A demand draft is issued by a bank after receiving the corresponding funds and is used as a payment instrument.","importantPoint":"Demand draft → bank-issued prepaid payment instrument.","examTrap":"It is not a deposit product or capital ratio.","hint":"Think bank-issued payment instrument."},{"id":"BS047","question":"Which of the following is most directly associated with bank liquidity risk?","options":[{"id":"A","text":"The possibility that the bank cannot meet obligations when due"},{"id":"B","text":"The possibility that a website changes colour"},{"id":"C","text":"The number of ATM screens"},{"id":"D","text":"The bank’s logo design"}],"answer":"A","explanation":"Liquidity risk concerns the ability to meet financial obligations as they fall due without unacceptable loss.","importantPoint":"Liquidity risk → ability to meet obligations.","examTrap":"Credit risk concerns borrower default, which is different.","hint":"Focus on meeting obligations on time."},{"id":"BS048","question":"Credit risk is primarily the risk that:","options":[{"id":"A","text":"A borrower or counterparty fails to meet financial obligations"},{"id":"B","text":"The bank has too much cash"},{"id":"C","text":"An ATM runs out of paper"},{"id":"D","text":"A website is unavailable"}],"answer":"A","explanation":"Credit risk is the risk of loss arising from a borrower or counterparty failing to meet contractual obligations.","importantPoint":"Credit risk → default/non-payment.","examTrap":"Liquidity and operational risks are different risk categories.","hint":"Think borrower default."},{"id":"BS049","question":"Operational risk primarily arises from:","options":[{"id":"A","text":"Inadequate or failed processes, people, systems or external events"},{"id":"B","text":"Only changes in stock prices"},{"id":"C","text":"Only borrower defaults"},{"id":"D","text":"Only foreign exchange movements"}],"answer":"A","explanation":"Operational risk includes losses from inadequate or failed internal processes, people and systems, or external events.","importantPoint":"Operational risk → people, process, systems, external events.","examTrap":"Borrower default is credit risk.","hint":"Recall the four broad sources."},{"id":"BS050","question":"Which of the following is an example of a cyber-related operational risk for a bank?","options":[{"id":"A","text":"Unauthorised access to customer systems"},{"id":"B","text":"A customer making a legitimate deposit"},{"id":"C","text":"A scheduled interest payment"},{"id":"D","text":"A normal ATM withdrawal"}],"answer":"A","explanation":"Unauthorised access is a cyber and operational risk because it can disrupt systems or compromise information.","importantPoint":"Cyber incidents can create operational and information-security risk.","examTrap":"Normal customer transactions are not cyber incidents.","hint":"Look for an unauthorised system event."}],"day-01-grammar-r01-r03":[{"id":"BG001","question":"Choose the grammatically correct sentence.","options":[{"id":"A","text":"Each of the candidates has submitted the application."},{"id":"B","text":"Each of the candidates have submitted the application."},{"id":"C","text":"Each candidates has submitted the application."},{"id":"D","text":"Each of candidates have submitted the application."}],"answer":"A","explanation":"The distributive pronoun “each” takes a singular verb: “has”.","importantPoint":"Each of + plural noun → singular verb.","examTrap":"The plural noun “candidates” does not control the verb.","hint":"Find the true grammatical subject."},{"id":"BG002","question":"Choose the grammatically correct sentence.","options":[{"id":"A","text":"Every employee is required to carry an identity card."},{"id":"B","text":"Every employees are required to carry an identity card."},{"id":"C","text":"Every employee are required to carry an identity card."},{"id":"D","text":"Every of employee is required to carry an identity card."}],"answer":"A","explanation":"“Every” is followed by a singular countable noun and takes a singular verb.","importantPoint":"Every + singular noun + singular verb.","examTrap":"Do not use a plural noun immediately after “every”.","hint":"Check the noun after “every”."},{"id":"BG003","question":"Choose the grammatically correct sentence.","options":[{"id":"A","text":"Both the proposals are technically feasible."},{"id":"B","text":"Both the proposal is technically feasible."},{"id":"C","text":"Both the proposals is technically feasible."},{"id":"D","text":"Both of proposal are technically feasible."}],"answer":"A","explanation":"“Both” refers to two entities and takes a plural noun and plural verb.","importantPoint":"Both + plural noun + plural verb.","examTrap":"“Both” does not take a singular verb when it is the subject.","hint":"Look at subject number."},{"id":"BG004","question":"Choose the grammatically correct sentence.","options":[{"id":"A","text":"Both of the applicants were shortlisted."},{"id":"B","text":"Both of the applicant was shortlisted."},{"id":"C","text":"Both of applicants was shortlisted."},{"id":"D","text":"Both applicants was shortlisted."}],"answer":"A","explanation":"“Both of the applicants” is a correct plural construction and takes “were”.","importantPoint":"Both of + plural noun → plural verb.","examTrap":"The noun after “of” must be plural in this construction.","hint":"Check the noun and verb together."},{"id":"BG005","question":"Choose the correct sentence.","options":[{"id":"A","text":"The manager spoke to Ravi and me."},{"id":"B","text":"The manager spoke to Ravi and I."},{"id":"C","text":"The manager spoke to Ravi and myself."},{"id":"D","text":"The manager spoke to Ravi and mine."}],"answer":"A","explanation":"After the preposition “to”, the objective pronoun “me” is required.","importantPoint":"Object after a preposition: me, him, her, us, them.","examTrap":"“I” is a subject form, not the object of “to”.","hint":"Remove “Ravi and” and test the pronoun."},{"id":"BG006","question":"Choose the correct sentence.","options":[{"id":"A","text":"Whom did you invite to the meeting?"},{"id":"B","text":"Who did you invite to the meeting?"},{"id":"C","text":"Whom invited you to the meeting?"},{"id":"D","text":"Who did you invited to the meeting?"}],"answer":"A","explanation":"“Whom” is used as the object of the verb “invite”.","importantPoint":"Who = subject; whom = object in formal usage.","examTrap":"Do not choose “who” merely because it is more common in speech.","hint":"Ask: whom did you invite?"},{"id":"BG007","question":"Choose the correct sentence.","options":[{"id":"A","text":"Who is responsible for preparing the report?"},{"id":"B","text":"Whom is responsible for preparing the report?"},{"id":"C","text":"Who are responsible for preparing the report?"},{"id":"D","text":"Whom are responsible for preparing the report?"}],"answer":"A","explanation":"“Who” is the subject of “is responsible”.","importantPoint":"Who functions as subject here.","examTrap":"“Whom” is objective case and cannot be the subject in this sentence.","hint":"Identify who performs the action/state."},{"id":"BG008","question":"Choose the correct sentence.","options":[{"id":"A","text":"To whom did the officer address the letter?"},{"id":"B","text":"To who did the officer address the letter?"},{"id":"C","text":"Whom did the officer addressed the letter?"},{"id":"D","text":"Who did the officer address to the letter?"}],"answer":"A","explanation":"After the preposition “to”, the formal objective form “whom” is used.","importantPoint":"Preposition + whom in formal grammar.","examTrap":"The verb after “did” must remain in base form.","hint":"Check both the preposition and verb form."},{"id":"BG009","question":"Choose the correct sentence.","options":[{"id":"A","text":"Neither of the two answers is correct."},{"id":"B","text":"Neither of the two answers are correct."},{"id":"C","text":"Neither of the two answer is correct."},{"id":"D","text":"Neither of two answers are correct."}],"answer":"A","explanation":"“Neither” is singular in standard formal usage and takes “is”.","importantPoint":"Neither of + plural noun → singular verb.","examTrap":"The plural noun after “of” does not make the verb plural.","hint":"Identify the head word of the subject."},{"id":"BG010","question":"Choose the correct sentence.","options":[{"id":"A","text":"Either of the routes is acceptable."},{"id":"B","text":"Either of the routes are acceptable."},{"id":"C","text":"Either of the route are acceptable."},{"id":"D","text":"Either routes is acceptable."}],"answer":"A","explanation":"“Either” is singular and takes “is” in this construction.","importantPoint":"Either of + plural noun → singular verb.","examTrap":"Do not let the nearby plural noun control the verb.","hint":"Focus on “either”."},{"id":"BG011","question":"Choose the correct sentence.","options":[{"id":"A","text":"One of the applicants has cleared the test."},{"id":"B","text":"One of the applicants have cleared the test."},{"id":"C","text":"One of the applicant has cleared the test."},{"id":"D","text":"One of applicants have cleared the test."}],"answer":"A","explanation":"The head word is “one”, so the verb is singular.","importantPoint":"One of + plural noun → singular verb.","examTrap":"The plural noun “applicants” does not control agreement.","hint":"Identify the head word “one”."},{"id":"BG012","question":"Choose the correct sentence.","options":[{"id":"A","text":"A number of students have registered for the course."},{"id":"B","text":"A number of students has registered for the course."},{"id":"C","text":"A number of student have registered for the course."},{"id":"D","text":"A number students has registered for the course."}],"answer":"A","explanation":"“A number of” means several and takes a plural noun and plural verb.","importantPoint":"A number of + plural noun → plural verb.","examTrap":"Do not confuse it with “the number of”.","hint":"Compare “a number of” with “the number of”."},{"id":"BG013","question":"Choose the correct sentence.","options":[{"id":"A","text":"The number of students has increased this year."},{"id":"B","text":"The number of students have increased this year."},{"id":"C","text":"The number of student have increased this year."},{"id":"D","text":"The numbers of students has increased this year."}],"answer":"A","explanation":"“The number” is singular and therefore takes “has”.","importantPoint":"The number of + plural noun → singular verb.","examTrap":"This is different from “a number of”.","hint":"Identify whether the phrase begins with “the number”."},{"id":"BG014","question":"Choose the correct sentence.","options":[{"id":"A","text":"Each boy and each girl was given a certificate."},{"id":"B","text":"Each boy and each girl were given a certificate."},{"id":"C","text":"Each boy and each girl have given a certificate."},{"id":"D","text":"Each boy and each girl are given a certificate."}],"answer":"A","explanation":"When “each” individually modifies the two subjects, the construction takes singular agreement.","importantPoint":"Each + singular subject → singular agreement.","examTrap":"Do not automatically use a plural verb because there are two noun phrases.","hint":"Look at the repeated “each”."},{"id":"BG015","question":"Choose the correct sentence.","options":[{"id":"A","text":"Every one of the machines is operational."},{"id":"B","text":"Every one of the machines are operational."},{"id":"C","text":"Every one of the machine are operational."},{"id":"D","text":"Every one machines is operational."}],"answer":"A","explanation":"“Every one” is singular and takes “is”.","importantPoint":"Every one of + plural noun → singular verb.","examTrap":"“Every one” is not the same as “everyone” in meaning or grammar.","hint":"Focus on “every one”."},{"id":"BG016","question":"Choose the correct sentence.","options":[{"id":"A","text":"Everyone in the department has completed the training."},{"id":"B","text":"Everyone in the department have completed the training."},{"id":"C","text":"Everyone in department have completed training."},{"id":"D","text":"Everyone in the departments has complete the training."}],"answer":"A","explanation":"“Everyone” is an indefinite pronoun that takes a singular verb.","importantPoint":"Everyone → singular verb.","examTrap":"The meaning may refer to many people, but grammatical number is singular.","hint":"Check the pronoun’s grammatical number."},{"id":"BG017","question":"Choose the correct sentence.","options":[{"id":"A","text":"Both of them are ready for the interview."},{"id":"B","text":"Both of them is ready for the interview."},{"id":"C","text":"Both of they are ready for the interview."},{"id":"D","text":"Both them are ready for the interview."}],"answer":"A","explanation":"“Both of them” is the correct plural construction.","importantPoint":"Both of + object pronoun.","examTrap":"“They” cannot follow “of” in this construction.","hint":"Check the pronoun case after “of”."},{"id":"BG018","question":"Choose the correct sentence.","options":[{"id":"A","text":"It was he who prepared the report."},{"id":"B","text":"It was him who prepared the report."},{"id":"C","text":"It was he whom prepared the report."},{"id":"D","text":"It was him which prepared the report."}],"answer":"A","explanation":"In formal traditional grammar, the complement after “It was” is “he”, and “who” is the subject of “prepared”.","importantPoint":"Formal exam grammar may require subject-form pronouns after linking verbs.","examTrap":"“Whom” cannot be the subject of “prepared”.","hint":"Check the role of “who” in the relative clause."},{"id":"BG019","question":"Choose the correct sentence.","options":[{"id":"A","text":"Whoever completes the task first will receive the certificate."},{"id":"B","text":"Whomever completes the task first will receive the certificate."},{"id":"C","text":"Whoever complete the task first will receive the certificate."},{"id":"D","text":"Whomsoever completes the task first will receive the certificate."}],"answer":"A","explanation":"“Whoever” is the subject of “completes” and therefore is appropriate.","importantPoint":"Whoever can function as a subject; whomever is objective.","examTrap":"Do not choose “whomever” merely because the sentence is formal.","hint":"Identify who performs “completes”."},{"id":"BG020","question":"Choose the correct sentence.","options":[{"id":"A","text":"The candidate whom the panel selected accepted the offer."},{"id":"B","text":"The candidate who the panel selected accepted the offer."},{"id":"C","text":"The candidate whom selected the panel accepted the offer."},{"id":"D","text":"The candidate who the panel selected accepted the offers."}],"answer":"A","explanation":"“Whom” is the object of “selected”: the panel selected whom.","importantPoint":"Relative pronoun as object → whom in formal usage.","examTrap":"“Who” is common in informal usage, but exam grammar may test formal case.","hint":"Ask: the panel selected whom?"},{"id":"BG021","question":"Choose the correct sentence.","options":[{"id":"A","text":"The officer who approved the request is on leave."},{"id":"B","text":"The officer whom approved the request is on leave."},{"id":"C","text":"The officer who the request approved is on leave."},{"id":"D","text":"The officer whom the request approved is on leave."}],"answer":"A","explanation":"“Who” is the subject of “approved”: the officer approved the request.","importantPoint":"Relative pronoun as subject → who.","examTrap":"Do not use “whom” when the pronoun performs the action.","hint":"Ask: who approved the request?"},{"id":"BG022","question":"Identify the grammatically correct sentence.","options":[{"id":"A","text":"Each of the files has been reviewed carefully."},{"id":"B","text":"Each of the files have been reviewed carefully."},{"id":"C","text":"Each of the file has been reviewed carefully."},{"id":"D","text":"Each files have been reviewed carefully."}],"answer":"A","explanation":"“Each” is singular and takes “has”; “files” is plural after “of”.","importantPoint":"Each of + plural noun → singular verb.","examTrap":"Do not make the verb agree with “files”.","hint":"Find the head word of the subject."},{"id":"BG023","question":"Identify the grammatically correct sentence.","options":[{"id":"A","text":"Every student and every teacher was informed."},{"id":"B","text":"Every student and every teacher were informed."},{"id":"C","text":"Every students and every teacher was informed."},{"id":"D","text":"Every student and every teacher have informed."}],"answer":"A","explanation":"Each singular subject introduced by “every” supports singular agreement in this coordinated construction.","importantPoint":"Every + singular noun.","examTrap":"The presence of two subjects does not automatically require “were” here.","hint":"Look at the form after each “every”."},{"id":"BG024","question":"Choose the correct sentence.","options":[{"id":"A","text":"Neither the manager nor the assistants were available."},{"id":"B","text":"Neither the manager nor the assistants was available."},{"id":"C","text":"Neither the manager nor the assistants is available."},{"id":"D","text":"Neither the manager nor the assistants has available."}],"answer":"A","explanation":"With “neither...nor”, the verb commonly agrees with the nearer subject; “assistants” is plural, so “were” is appropriate.","importantPoint":"Neither...nor → verb agreement follows the nearer subject in standard usage.","examTrap":"Do not automatically make the verb singular because of “neither”.","hint":"Check the subject nearest to the verb."},{"id":"BG025","question":"Choose the correct sentence.","options":[{"id":"A","text":"Neither the assistants nor the manager was available."},{"id":"B","text":"Neither the assistants nor the manager were available."},{"id":"C","text":"Neither the assistants nor the manager are available."},{"id":"D","text":"Neither assistants nor manager have available."}],"answer":"A","explanation":"The nearer subject is singular “manager”, so “was” is appropriate.","importantPoint":"Neither...nor → agreement with the nearer subject.","examTrap":"Changing subject order can change the verb form.","hint":"Look at the noun closest to the verb."},{"id":"BG026","question":"Choose the correct sentence.","options":[{"id":"A","text":"Either the manager or the assistants are responsible."},{"id":"B","text":"Either the manager or the assistants is responsible."},{"id":"C","text":"Either the manager or the assistants was responsible."},{"id":"D","text":"Either manager or assistants has responsible."}],"answer":"A","explanation":"With “either...or”, the verb agrees with the nearer subject “assistants”.","importantPoint":"Either...or → agreement with the nearer subject.","examTrap":"Do not always use singular agreement after “either”.","hint":"Check the nearer subject."},{"id":"BG027","question":"Choose the correct sentence.","options":[{"id":"A","text":"Either the assistants or the manager is responsible."},{"id":"B","text":"Either the assistants or the manager are responsible."},{"id":"C","text":"Either the assistants or the manager have responsible."},{"id":"D","text":"Either assistants or manager were responsible."}],"answer":"A","explanation":"The nearer subject is singular “manager”, so “is” is appropriate.","importantPoint":"Either...or → nearer-subject agreement.","examTrap":"Subject order matters for agreement.","hint":"Look immediately before the verb."},{"id":"BG028","question":"Choose the correct sentence.","options":[{"id":"A","text":"The quality of these products is excellent."},{"id":"B","text":"The quality of these products are excellent."},{"id":"C","text":"The qualities of these products is excellent."},{"id":"D","text":"The quality these products are excellent."}],"answer":"A","explanation":"The head noun is singular “quality”, so the verb is “is”.","importantPoint":"Prepositional phrases do not change the number of the head noun.","examTrap":"Do not make the verb agree with the plural noun “products”.","hint":"Find the main noun before “of”."},{"id":"BG029","question":"Choose the correct sentence.","options":[{"id":"A","text":"The list of shortlisted candidates is on the desk."},{"id":"B","text":"The list of shortlisted candidates are on the desk."},{"id":"C","text":"The lists of shortlisted candidates is on the desk."},{"id":"D","text":"The list shortlisted candidates are on the desk."}],"answer":"A","explanation":"The head noun “list” is singular and takes “is”.","importantPoint":"Head noun controls agreement.","examTrap":"The plural noun “candidates” is inside an “of” phrase.","hint":"Ignore the intervening plural noun and find the head."},{"id":"BG030","question":"Choose the correct sentence.","options":[{"id":"A","text":"More than one candidate has qualified."},{"id":"B","text":"More than one candidate have qualified."},{"id":"C","text":"More than one candidates has qualified."},{"id":"D","text":"More than one candidate are qualified."}],"answer":"A","explanation":"“More than one” generally takes a singular noun and singular verb in standard exam grammar.","importantPoint":"More than one + singular noun + singular verb.","examTrap":"Do not treat the phrase as a normal plural expression.","hint":"Recall the fixed agreement pattern."},{"id":"BG031","question":"Choose the correct sentence.","options":[{"id":"A","text":"Many a student has made this mistake."},{"id":"B","text":"Many a student have made this mistake."},{"id":"C","text":"Many a students has made this mistake."},{"id":"D","text":"Many students has made this mistake."}],"answer":"A","explanation":"“Many a” takes a singular noun and singular verb.","importantPoint":"Many a + singular noun + singular verb.","examTrap":"Do not use a plural noun after “many a”.","hint":"Recognise the fixed construction."},{"id":"BG032","question":"Choose the correct sentence.","options":[{"id":"A","text":"There are several reasons for the delay."},{"id":"B","text":"There is several reasons for the delay."},{"id":"C","text":"There are a reason for the delay."},{"id":"D","text":"There is several reason for the delay."}],"answer":"A","explanation":"The real subject “several reasons” is plural, so “are” is required.","importantPoint":"In existential constructions, agreement follows the notional subject.","examTrap":"Do not let “there” determine the verb number.","hint":"Identify what actually exists."},{"id":"BG033","question":"Choose the correct sentence.","options":[{"id":"A","text":"There is a problem with the server."},{"id":"B","text":"There are a problem with the server."},{"id":"C","text":"There is problems with the server."},{"id":"D","text":"There are problem with the server."}],"answer":"A","explanation":"The real subject “a problem” is singular, so “is” is required.","importantPoint":"There is + singular noun.","examTrap":"“There” itself has no number for agreement.","hint":"Look at the noun after the verb."},{"id":"BG034","question":"Choose the correct sentence.","options":[{"id":"A","text":"The news is encouraging."},{"id":"B","text":"The news are encouraging."},{"id":"C","text":"The news were encouraging."},{"id":"D","text":"The news have encouraging."}],"answer":"A","explanation":"“News” is grammatically singular despite ending in “s”.","importantPoint":"News → singular noun.","examTrap":"Do not infer plural agreement from the final “s”.","hint":"Check whether “news” is countable in this use."},{"id":"BG035","question":"Choose the correct sentence.","options":[{"id":"A","text":"Mathematics is an important subject for the exam."},{"id":"B","text":"Mathematics are an important subject for the exam."},{"id":"C","text":"Mathematics have an important subject for the exam."},{"id":"D","text":"Mathematics were an important subject for the exam."}],"answer":"A","explanation":"“Mathematics” is singular when referring to the academic subject.","importantPoint":"Names of academic subjects ending in -s often take singular verbs.","examTrap":"The spelling does not determine grammatical number by itself.","hint":"Treat the subject name as one field of study."},{"id":"BG036","question":"Choose the correct sentence.","options":[{"id":"A","text":"The police have arrested the suspect."},{"id":"B","text":"The police has arrested the suspect."},{"id":"C","text":"The police is arrested the suspect."},{"id":"D","text":"The police was arrested the suspect."}],"answer":"A","explanation":"“Police” is generally treated as a plural noun when referring to police officers collectively.","importantPoint":"Police → plural agreement in standard usage.","examTrap":"Do not use “polices” or singular agreement in this meaning.","hint":"Consider whether the noun refers to officers as a group."},{"id":"BG037","question":"Choose the correct sentence.","options":[{"id":"A","text":"The committee has submitted its report."},{"id":"B","text":"The committee have submitted its report."},{"id":"C","text":"The committee has submitted their report."},{"id":"D","text":"The committee were submitted its report."}],"answer":"A","explanation":"In formal singular collective-noun usage, “committee” takes “has” and the singular possessive “its”.","importantPoint":"Singular collective noun → singular agreement when acting as a unit.","examTrap":"Do not mix singular verb with plural possessive in a formal exam sentence.","hint":"Treat the committee as one unit here."},{"id":"BG038","question":"Choose the correct sentence.","options":[{"id":"A","text":"The committee have disagreed among themselves."},{"id":"B","text":"The committee has disagreed among themselves."},{"id":"C","text":"The committee have disagreed among itself."},{"id":"D","text":"The committee has disagreed among itself."}],"answer":"A","explanation":"When members act individually, a collective noun can take plural agreement in British-style usage; “themselves” supports the plural sense.","importantPoint":"Collective nouns may take plural agreement when members act separately.","examTrap":"Agreement depends on whether the group acts as a unit or individuals.","hint":"Look for “among themselves”."},{"id":"BG039","question":"Choose the correct sentence.","options":[{"id":"A","text":"I am one of those employees who work overtime."},{"id":"B","text":"I am one of those employees who works overtime."},{"id":"C","text":"I am one of those employee who work overtime."},{"id":"D","text":"I am one those employees who works overtime."}],"answer":"A","explanation":"The relative pronoun “who” refers to plural “employees”, so “work” is appropriate.","importantPoint":"Relative-pronoun agreement depends on its antecedent.","examTrap":"Do not automatically make “who” singular because the sentence begins with “I”.","hint":"Find the noun immediately governing “who”."},{"id":"BG040","question":"Choose the correct sentence.","options":[{"id":"A","text":"She is the only one of the candidates who has cleared the interview."},{"id":"B","text":"She is the only one of the candidates who have cleared the interview."},{"id":"C","text":"She is the only one of candidates who have cleared the interview."},{"id":"D","text":"She is only one of the candidates who has clear the interview."}],"answer":"A","explanation":"“Who” refers to “the only one”, which is singular, so “has” is appropriate.","importantPoint":"Only one of + plural noun → relative clause may take singular agreement when “who” refers to one.","examTrap":"Distinguish “one of” from “the only one of”.","hint":"Identify the antecedent of “who”."},{"id":"BG041","question":"Choose the correct sentence.","options":[{"id":"A","text":"Neither of them knows the answer."},{"id":"B","text":"Neither of them know the answer."},{"id":"C","text":"Neither them knows the answer."},{"id":"D","text":"Neither of they knows the answer."}],"answer":"A","explanation":"“Neither” is singular in formal grammar and takes “knows”; “them” is the object form after “of”.","importantPoint":"Neither of + object pronoun + singular verb.","examTrap":"Do not use “they” after “of”.","hint":"Check pronoun case and subject number."},{"id":"BG042","question":"Choose the correct sentence.","options":[{"id":"A","text":"Whom did the interviewer select for the final round?"},{"id":"B","text":"Who did the interviewer selected for the final round?"},{"id":"C","text":"Whom did the interviewer selected for the final round?"},{"id":"D","text":"Who did the interviewer select for the final round?"}],"answer":"A","explanation":"In formal grammar, “whom” is the object of “select”, and “did” requires the base verb “select”.","importantPoint":"Whom = object; did + base verb.","examTrap":"There are two traps: pronoun case and verb form after “did”.","hint":"Check both the pronoun’s role and the auxiliary."},{"id":"BG043","question":"Choose the correct sentence.","options":[{"id":"A","text":"Who did you say was responsible for the error?"},{"id":"B","text":"Whom did you say was responsible for the error?"},{"id":"C","text":"Who did you said was responsible for the error?"},{"id":"D","text":"Whom did you said was responsible for the error?"}],"answer":"A","explanation":"“Who” is the subject of “was responsible”; “did you say” correctly uses the base verb “say”.","importantPoint":"Case is determined by the pronoun’s role in its clause.","examTrap":"Do not choose “whom” simply because “did” appears earlier.","hint":"Find the verb that the pronoun actually controls."},{"id":"BG044","question":"Choose the correct sentence.","options":[{"id":"A","text":"To whom should I send the revised document?"},{"id":"B","text":"To who should I send the revised document?"},{"id":"C","text":"To whom should I sent the revised document?"},{"id":"D","text":"To who should I sent the revised document?"}],"answer":"A","explanation":"“Whom” follows the preposition “to”, and “should” is followed by the base verb “send”.","importantPoint":"Preposition + whom; modal + base verb.","examTrap":"Do not use “sent” after “should”.","hint":"Check both grammar points."},{"id":"BG045","question":"Choose the correct sentence.","options":[{"id":"A","text":"Both of the reports are accurate."},{"id":"B","text":"Both of the reports is accurate."},{"id":"C","text":"Both of the report are accurate."},{"id":"D","text":"Both reports is accurate."}],"answer":"A","explanation":"“Both” takes a plural noun and plural verb.","importantPoint":"Both → plural agreement.","examTrap":"The singular “is” is not compatible with the plural subject.","hint":"Check the subject number."},{"id":"BG046","question":"Choose the correct sentence.","options":[{"id":"A","text":"Every one of these documents is confidential."},{"id":"B","text":"Every one of these documents are confidential."},{"id":"C","text":"Every one these documents is confidential."},{"id":"D","text":"Every one of these document are confidential."}],"answer":"A","explanation":"“Every one” is singular and takes “is”; “documents” remains plural after “of”.","importantPoint":"Every one of + plural noun → singular verb.","examTrap":"Do not confuse “every one” with “everyone”.","hint":"Focus on the head phrase “every one”."},{"id":"BG047","question":"Choose the correct sentence.","options":[{"id":"A","text":"Everyone who applies must provide valid identification."},{"id":"B","text":"Everyone who applies must provides valid identification."},{"id":"C","text":"Everyone who apply must provide valid identification."},{"id":"D","text":"Everyone who applies must providing valid identification."}],"answer":"A","explanation":"“Everyone” is singular, “who applies” agrees with everyone, and modal “must” takes the base verb “provide”.","importantPoint":"Everyone + singular verb; modal + base verb.","examTrap":"There are two separate agreement/verb-form checks.","hint":"Check the relative clause and the modal."},{"id":"BG048","question":"Choose the correct sentence.","options":[{"id":"A","text":"Each of the two proposals has a different risk profile."},{"id":"B","text":"Each of the two proposals have a different risk profile."},{"id":"C","text":"Each of the two proposal has a different risk profile."},{"id":"D","text":"Each the two proposals has a different risk profile."}],"answer":"A","explanation":"“Each” is singular and takes “has”; “proposals” is plural after “of”.","importantPoint":"Each → singular agreement.","examTrap":"The presence of “two” does not make “each” plural.","hint":"Focus on the distributive meaning."},{"id":"BG049","question":"Choose the correct sentence.","options":[{"id":"A","text":"The person whom I met yesterday was the branch manager."},{"id":"B","text":"The person who I met yesterday were the branch manager."},{"id":"C","text":"The person whom I meet yesterday was the branch manager."},{"id":"D","text":"The person who I met yesterday were branch manager."}],"answer":"A","explanation":"“Whom” is the object of “met”, and the main subject “person” takes singular “was”.","importantPoint":"Relative object → whom; singular main subject → was.","examTrap":"Do not let “I” determine the main verb.","hint":"Identify the object of “met”."},{"id":"BG050","question":"Choose the correct sentence.","options":[{"id":"A","text":"The applicants who submitted the forms on time were shortlisted."},{"id":"B","text":"The applicants whom submitted the forms on time were shortlisted."},{"id":"C","text":"The applicants who submitted the forms on time was shortlisted."},{"id":"D","text":"The applicant who submitted the forms on time were shortlisted."}],"answer":"A","explanation":"“Who” is the subject of “submitted”, and plural “applicants” takes “were”.","importantPoint":"Who as subject; plural antecedent → plural verb.","examTrap":"“Whom” would be incorrect because the pronoun performs the action.","hint":"Ask: who submitted?"}]};
